---------------------------------------------
; Default record for the 16 unused scene ids: the player (tile 2,9, attribute $02), camera_scroll_controller and ScrollCameraTrack, title TEST MAP. Reached only if one of those ids is loaded; nothing found loads one.

scene_default_actors [
  actor-spawn < #02, #09, #02, @player_character.PlayerCharacterDef >   ;00
  actor-spawn < #00, #00, #00, @camera_scroll_controller >   ;01
  actor-spawn < #11, #11, #00, @camera_scroll.ScrollCameraTrack >   ;02
]

